#include "dk1/player_input_router.h"
#include <string.h>
static bool push(Dk1PlayerInputRoute *route, Dk1PlayerInputAction action) { if (route->action_count >= DK1_PLAYER_INPUT_ACTION_CAPACITY) return false; route->actions[route->action_count++] = action; return true; }
bool dk1_player_input_route(uint16_t mode_argument,uint16_t held,uint16_t pressed,uint16_t flags_1917,Dk1PlayerInputRoute *route) { if (route == NULL) return false; memset(route, 0, sizeof(*route)); route->mode_argument_180f=mode_argument; route->held=held; route->pressed=pressed; route->flags_1917=flags_1917; if(!push(route,(held&0x0800u)?DK1_PLAYER_INPUT_UP:((held&0x0400u)?DK1_PLAYER_INPUT_DOWN:DK1_PLAYER_INPUT_VERTICAL_NEUTRAL)))return false; if(!push(route,(held&0x0200u)?DK1_PLAYER_INPUT_LEFT:((held&0x0100u)?DK1_PLAYER_INPUT_RIGHT:DK1_PLAYER_INPUT_HORIZONTAL_NEUTRAL)))return false; if((held&0x0080u)&&!push(route,DK1_PLAYER_INPUT_SELECT))return false; if(!push(route,(held&0x8000u)?DK1_PLAYER_INPUT_A_HELD:DK1_PLAYER_INPUT_A_RELEASED))return false; if((held&0x0040u)&&!push(route,DK1_PLAYER_INPUT_Y))return false; if(!push(route,(held&0x4000u)?DK1_PLAYER_INPUT_X_HELD:DK1_PLAYER_INPUT_X_RELEASED))return false; if((held&0x0020u)&&!push(route,DK1_PLAYER_INPUT_L))return false; if((held&0x0010u)&&!push(route,DK1_PLAYER_INPUT_R))return false; if(held&0x2000u){if(!push(route,DK1_PLAYER_INPUT_B_HELD))return false;}else{route->flags_1917&=0xFFBFu;if(!push(route,DK1_PLAYER_INPUT_B_RELEASED))return false;} if((held&0x1000u)&&!push(route,DK1_PLAYER_INPUT_START))return false; return true; }
